#!/usr/bin/env bash
#
# fix-treasury-A2-batch-table.sh   (Item A, Phase A2)
#
# WHAT: Replaces the recent-payrolls LIST on /treasury with a Settlements-style
#       TABBED TABLE: tabs All / Completed / Processing / Failed (each with a
#       count) + a batch table (Batch | Recipients | Total USD | Chain | Date |
#       Status | ->), click-through to /treasury/payroll/[id] preserved.
#
# WHY:  Brings the payroll dashboard in line with /settlements (the invoice
#       dashboard). Sets up A3 (per-recipient CSV export).
#
# SCOPE: web only, ONE file, FULL-FILE REPLACEMENT of
#        nexum-web/app/(app)/treasury/TreasuryContent.tsx.
#        Header, range selector and the 3 USD summary cards from A1 are unchanged.
#
# PRECONDITION: A1 applied (file == the A1 dashboard shell). The guard below
#        checks the CURRENT file matches the known A1 SHA; if it does not, the
#        script still applies safely (backs up whatever is there first) but warns.
#
# DELIVERY: v2 - base64 payload decoded to temp, SHA-256 verified BEFORE replace,
#           backup-once, idempotent (skips if target already == A2 SHA), --revert.
#
# USAGE:
#   bash fix-treasury-A2-batch-table.sh          # apply
#   bash fix-treasury-A2-batch-table.sh --revert # restore newest backup
#
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$REPO_ROOT"

TARGET="nexum-web/app/(app)/treasury/TreasuryContent.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
EXPECTED_SHA="4599b5dbef3fa7906830a51a1deac1f54e241beb1610a580b14c815573b2e56b"
A1_SHA="f93ca91fd3da298d38ba8b2b43ecf83d5919c17366549474a2c97079face8d95"

# ----- revert -----
if [ "${1:-}" = "--revert" ]; then
  newest="$(ls -1t "$TARGET".bak.* 2>/dev/null | head -1 || true)"
  if [ -z "$newest" ]; then echo "revert: no backup for $TARGET"; exit 1; fi
  cp "$newest" "$TARGET"; echo "reverted $TARGET from $newest"
  exit 0
fi

[ -f "$TARGET" ] || { echo "ABORT: $TARGET not found" >&2; exit 1; }

# ----- idempotency -----
if command -v sha256sum >/dev/null 2>&1; then
  CUR_SHA="$(sha256sum "$TARGET" | awk '{print $1}')"
  if [ "$CUR_SHA" = "$EXPECTED_SHA" ]; then
    echo "already applied: $TARGET matches A2 content - nothing to do"; exit 0
  fi
  if [ "$CUR_SHA" != "$A1_SHA" ]; then
    echo "WARN: $TARGET is neither the A1 shell nor A2 (SHA $CUR_SHA). Backing up and applying anyway." >&2
  fi
fi

# ----- decode + verify BEFORE touching target -----
TMP="$(mktemp)"; trap 'rm -f "$TMP" "$TMP.b64"' EXIT
cat > "$TMP.b64" <<'B64EOF'

B64EOF
base64 -d "$TMP.b64" > "$TMP"
GOT_SHA="$(sha256sum "$TMP" | awk '{print $1}')"
if [ "$GOT_SHA" != "$EXPECTED_SHA" ]; then
  echo "ABORT: decoded payload SHA mismatch ($GOT_SHA != $EXPECTED_SHA). Target untouched." >&2
  exit 1
fi

cp "$TARGET" "$TARGET.bak.$STAMP"
cp "$TMP" "$TARGET"
echo "OK: $TARGET replaced with A2 tabbed batch table (backup: $TARGET.bak.$STAMP)"
echo ""
echo "Done. Standard deploy (web only):"
echo "  cd ~/AfriFX/nexum-web && rm -rf .next && npx tsc --noEmit && npm run build"
echo "  cd ~/AfriFX && git add -A && git commit -m 'feat: payroll dashboard tabbed batch table (A2)' && git push"
